39	static const std::initializer_list<op::DataType> DTYPE_SUPPORT_LIST_QUANT = {op::DataType::DT_INT8};
40	
41	static const std::initializer_list<op::DataType> DTYPE_SUPPORT_LIST_DEQUANT = {
42	    op::DataType::DT_UINT64, op::DataType::DT_INT64, op::DataType::DT_BF16, op::DataType::DT_FLOAT};
43	
44	static const std::initializer_list<op::DataType> DTYPE_SUPPORT_LIST_PERTOKEN = {op::DataType::DT_FLOAT};
45	
46	static const std::initializer_list<op::DataType> DTYPE_SUPPORT_LIST_DEQUANT_310P = {op::DataType::DT_UINT64,
47	                                                                                    op::DataType::DT_INT64};
48	
49	bool MatmulAllReduceCheckFormat(const aclTensor *x2)
50	{
51	    // 非量化不支持B矩阵转置
52	    bool isWeightNZ = MatmulAllReduceIsWeightNZFormat(x2);
53	    OP_LOGI("MatmulAllReduce, is Weigth NZ: %d", isWeightNZ);
54	    if (isWeightNZ) {
55	        OP_LOGE_FOR_INVALID_FORMAT("MatmulAllReduce", "x2", "FRACTAL_NZ", "ND");
56	        return false;
57	    }
58	    return true;
59	}
60	
61	bool MatmulAllReduceCheckValidEmptyTensor(const aclTensor *x1, const aclTensor *x2)
62	{
63	    OP_CHECK_NULL(x1, return false);
64	    OP_CHECK_NULL(x2, return false);
65	    // 当输入tensor的shape小于2或者大于6的时候，返回错误
66	    if (x2->GetViewShape().GetDimNum() < 2 || x2->GetViewShape().GetDimNum() > 6) {
67	        return false;
68	    }
69	    int64_t dim1 = x2->GetViewShape().GetDimNum() - 1;
70	    int64_t dim2 = x2->GetViewShape().GetDimNum() - 2;
71	    int64_t m = x1->GetViewShape().GetDim(dim1);
72	    int64_t k = x2->GetViewShape().GetDim(dim1);
73	    int64_t n = x2->GetViewShape().GetDim(dim2);
74	    // 空tensor放行
75	    if (m == 0 || k == 0 || n == 0) {
76	        return true;
77	    }
78	    return false;
79	}
80	
81	bool MatmulAllReduceCheckValidContiguous(const aclTensor *tensor, const char *tensorName)
82	{
83	    bool isTransposeX2 = IsTransposeLastTwoDims(tensor);
84	    // x2非连续时仅支持转置场景
85	    if (!isTransposeX2 && !MC2Aclnn::IsTensorContiguous(tensor)) {
86	        OP_LOGE_FOR_INVALID_VALUE_WITH_REASON("MatmulAllReduce", tensorName, "non-contiguous",
87	                                              "The value of tensor without transpose must be contiguous");
88	        return false;
89	    }
90	    return true;
91	}
92	
93	aclnnStatus MatmulAllReduceCheckParams(const aclTensor *x1, const aclTensor *x2, const aclTensor *x3,
94	                                       const aclTensor *bias, const char *reduceOp, int64_t streamMode,
95	                                       const aclTensor *output)
96	{
97	    const static bool is310P = op::GetCurrentPlatformInfo().GetCurNpuArch() == NpuArch::DAV_2002;
98	
99	    // 1. 检查参数是否为空指针
100	    CHECK_RET(MatmulAllReduceCheckNotNull(x1, x2, output), ACLNN_ERR_PARAM_NULLPTR);
101	
102	    // 2. 检查输入的数据类型是否在API支持的数据类型范围之内，需要根据api定义校验
103	    CHECK_RET(MatmulAllReduceCheckDtypeValid(x1, x2, x3, bias, output, is310P), ACLNN_ERR_PARAM_INVALID);
104	
105	    // 3. 检查attr是否符合规则
106	    CHECK_RET(MatmulAllReduceCheckAttr(reduceOp, streamMode), ACLNN_ERR_PARAM_INVALID);
107	
108	    // 4. 非量化场景不支持B矩阵Nz格式 除了310P
109	    if (!is310P) {
110	        CHECK_RET(MatmulAllReduceCheckFormat(x2), ACLNN_ERR_PARAM_INVALID);
111	    }
112	
113	    // 5. 检查输出shape
114	    CHECK_RET(MatmulAllReduceCheckShape(x1, x2, x3, bias, output), ACLNN_ERR_PARAM_INVALID);
115	
116	    // 6.【A2】检查x2矩阵非连续合法性
117	    if (op::GetCurrentPlatformInfo().GetSocVersion() == SocVersion::ASCEND910B &&
118	        !MatmulAllReduceCheckValidEmptyTensor(x1, x2)) {
119	        CHECK_RET(MatmulAllReduceCheckValidContiguous(x2, "x2"), ACLNN_ERR_PARAM_INVALID);
120	    }
121	
122	    if (is310P && x3 != nullptr) {
123	        return ACLNN_ERR_PARAM_INVALID;
124	    }
125	
126	    return ACLNN_SUCCESS;
127	}
128	
129	// 检查入参是否为nullptr
130	bool MatmulAllReduceCheckNotNull(const aclTensor *x1, const aclTensor *x2, const aclTensor *output)
131	{
132	    OP_CHECK_NULL(x1, return false);
133	    OP_CHECK_NULL(x2, return false);
134	    OP_CHECK_NULL(output, return false);
135	    return true;
136	}
137	
138	bool MatmulAllReduceCheckDtypeValid(const aclTensor *x1, const aclTensor *x2, const aclTensor *x3,
139	                                    const aclTensor *bias, const aclTensor *output, bool is310P)
140	{
141	    const auto &dtypeSupportList = is310P ? DTYPE_SUPPORT_LIST_310P : DTYPE_SUPPORT_LIST;
142	    // 检查x1、x2、bias、output的数据类型是否在算子的支持列表内
143	    OP_CHECK_DTYPE_NOT_SUPPORT(x1, dtypeSupportList, return false);
144	    OP_CHECK_DTYPE_NOT_SUPPORT(x2, dtypeSupportList, return false);
145	    OP_CHECK_DTYPE_NOT_SUPPORT(output, dtypeSupportList, return false);
146	    // 检查bias的数据类型是否在算子的支持列表内
147	    if (bias != nullptr) {
148	        OP_CHECK_DTYPE_NOT_SUPPORT(bias, dtypeSupportList, return false);
149	    }
150	
151	    if (x3 != nullptr) {
152	        // 检查x3的数据类型是否在算子的支持列表内
153	        OP_CHECK_DTYPE_NOT_SUPPORT(x3, dtypeSupportList, return false);
154	        // 检查x1和x3的数据类型是否相同
155	        OP_CHECK_DTYPE_NOT_SAME(x1, x3, return false);
156	    }
157	    // 检查x1和x2的数据类型是否相同
158	    OP_CHECK_DTYPE_NOT_SAME(x1, x2, return false);
159	    // 检查x1和output的数据类型是否相同
160	    OP_CHECK_DTYPE_NOT_SAME(x1, output, return false);
161	    // 检查output和bias的数据类型是否相同
162	    if (bias != nullptr) {
163	        OP_CHECK_DTYPE_NOT_SAME(bias, x1, return false);
164	    }
165	    return true;
166	}
167	
168	// 检查传入的reduction数值是否在可选范围内
169	bool MatmulAllReduceCheckAttr(const char *reduceOp, int64_t streamMode)
170	{
171	    bool flag = (strcmp(reduceOp, REDUCE_OP_SUM) == 0);
172	    if (!flag) {
173	        OP_LOGE_FOR_INVALID_VALUE("MatmulAllReduce", "reduceOp", reduceOp, "\"sum\"");
174	        return false;
175	    }
176	    if (streamMode != NUM_ACL_STOP_ON_FAILURE) {
177	        OP_LOGE_FOR_INVALID_VALUE("MatmulAllReduce", "streamMode", std::to_string(streamMode).c_str(), "\"1\"");
178	        return false;
179	    }
180	    return true;
181	}
182	
183	bool MatmulAllReduceCheckShape(const aclTensor *x1, const aclTensor *x2, const aclTensor *x3, const aclTensor *bias,
184	                               const aclTensor *output)
185	{
186	    bool isWeightNZ = MatmulAllReduceIsWeightNZFormat(x2);
187	    uint64_t weightDim = isWeightNZ ? FOUR_DIMS : TWO_DIMS;
188	    // x2的维度为2维,x1的维度为2D或者3D，output的维数与x1一致,weightNZ场景下，x2可能为4维
189	    if (x2->GetViewShape().GetDimNum() != weightDim) {
190	        OP_LOGE_FOR_INVALID_SHAPEDIM_WITH_REASON(
191	            "MatmulAllReduce", "x2", (std::to_string(x2->GetViewShape().GetDimNum()) + "D").c_str(),
192	            ("The shape of x2 must be " + std::to_string(weightDim) + "D.").c_str());
193	        return false;
194	    }
195	    OP_CHECK_MIN_DIM(x1, TWO_DIMS, return false);
196	    OP_CHECK_MAX_DIM(x1, THREE_DIMS, return false);
197	    if (isWeightNZ) {
198	        return true;
199	    }
200	    // 仅支持x2矩阵转置，x1不支持转置, x1.GetDimNum(1) == x2.GetDimNum(0)
201	    const size_t x1_len = x1->GetViewShape().GetDimNum();
202	    if (x1->GetViewShape().GetDim(x1_len - 1) != x2->GetViewShape().GetDim(0)) {
203	        OP_LOGE_FOR_INVALID_SHAPE_WITH_REASON(
204	            "MatmulAllReduce", "x1", op::ToString(x1->GetViewShape()).GetString(),
205	            std::string("The last dim of x1 must be equal to the first dim of x2, but x2 shape is " +
206	                        std::string(op::ToString(x2->GetViewShape()).GetString()))
207	                .c_str());
208	        return false;
209	    }
210	
211	    // output的最后一维与x2的最后一维相同
212	    op::Shape outShape = x1->GetViewShape();
213	    outShape.SetDim(x1_len - 1, x2->GetViewShape().GetDim(1));
214	    OP_CHECK_SHAPE_NOT_EQUAL_WITH_EXPECTED_SIZE(output, outShape, return false);
215	
216	    if (x3 != nullptr) {
217	        OP_CHECK_SHAPE_NOT_EQUAL(output, x3, return false);
218	    }
219	
220	    // x1 shape [s,m,k], x2 shape [k,n], output shape [s,m,n], bias shape [n]
221	    if (bias != nullptr) {
222	        if (bias->GetViewShape().GetDimNum() != ONE_DIM) {
223	            OP_LOGE_FOR_INVALID_SHAPEDIM_WITH_REASON("MatmulAllReduce", "bias",
224	                                                     (std::to_string(bias->GetViewShape().GetDimNum()) + "D").c_str(),
225	                                                     "The shape of bias must be 1D.");
226	            return false;
227	        }
228	        op::Shape biasShape;
229	        biasShape.AppendDim(output->GetViewShape().GetDim(x1_len - 1));
230	        OP_CHECK_SHAPE_NOT_EQUAL_WITH_EXPECTED_SIZE(bias, biasShape, return false);
231	    }
232	    return true;
233	}
234	
235	// 全量化场景
236	aclnnStatus QuantMatmulAllReduceCheckParams(const aclTensor *x1, const aclTensor *x2, const aclTensor *bias,
237	                                            const aclTensor *dequantScale, const aclTensor *pertokenScale,
238	                                            const aclTensor *x3, const char *reduceOp, int64_t streamMode,
239	                                            const aclTensor *output)
240	{
241	    // 1. 检查参数是否为空指针
242	    CHECK_RET(MatmulAllReduceCheckNotNull(x1, x2, output), ACLNN_ERR_PARAM_NULLPTR);
243	    OP_CHECK_NULL(dequantScale, return ACLNN_ERR_PARAM_NULLPTR);
244	
245	    // 2. 检查输入的数据类型是否在API支持的数据类型范围之内，需要根据api定义校验
246	    CHECK_RET(QuantMatmulAllReduceCheckDtypeValid(x1, x2, bias, dequantScale, pertokenScale, x3, output),
247	              ACLNN_ERR_PARAM_INVALID);
248	
249	    // 3. 检查attr是否符合规则
250	    CHECK_RET(MatmulAllReduceCheckAttr(reduceOp, streamMode), ACLNN_ERR_PARAM_INVALID);
251	
252	    // 4. 检查输出shape
253	    CHECK_RET(QuantMatmulAllReduceCheckShape(x1, x2, bias, dequantScale, pertokenScale, x3, output),
254	              ACLNN_ERR_PARAM_INVALID);
255	
256	    // 5.【A2】检查x2矩阵非连续合法性
257	    if (op::GetCurrentPlatformInfo().GetSocVersion() == SocVersion::ASCEND910B &&
258	        !MatmulAllReduceCheckValidEmptyTensor(x1, x2)) {
259	        CHECK_RET(MatmulAllReduceCheckValidContiguous(x2, "x2"), ACLNN_ERR_PARAM_INVALID);
260	    }
261	
262	    return ACLNN_SUCCESS;
263	}
