265	bool QuantMatmulAllReduceCheckDtypeValid(const aclTensor *x1, const aclTensor *x2, const aclTensor *bias,
266	                                         const aclTensor *dequantScale, const aclTensor *pertokenScale,
267	                                         const aclTensor *x3, const aclTensor *output)
268	{
269	    const auto &dequantDtypeSupport = op::GetCurrentPlatformInfo().GetCurNpuArch() == NpuArch::DAV_2002 ?
270	                                          DTYPE_SUPPORT_LIST_DEQUANT_310P :
271	                                          DTYPE_SUPPORT_LIST_DEQUANT;
272	
273	    const auto &outDtypeSupport = op::GetCurrentPlatformInfo().GetCurNpuArch() == NpuArch::DAV_2002 ?
274	                                      DTYPE_SUPPORT_LIST_310P :
275	                                      DTYPE_SUPPORT_LIST;
276	
277	    // 检查x1、x2、bias、scale、offset、x3、output的数据类型是否在算子的支持列表内
278	    // 对于量化来说，x1,x2只为INT8
279	    OP_CHECK_DTYPE_NOT_SUPPORT(x1, DTYPE_SUPPORT_LIST_QUANT, return false);
280	    OP_CHECK_DTYPE_NOT_SUPPORT(x2, DTYPE_SUPPORT_LIST_QUANT, return false);
281	    OP_CHECK_DTYPE_NOT_SUPPORT(dequantScale, dequantDtypeSupport, return false);
282	    OP_CHECK_DTYPE_NOT_SUPPORT(output, outDtypeSupport, return false);
283	    // 检查bias、offset、x3的数据类型是否在算子的支持列表内
284	    if (bias != nullptr) {
285	        OP_CHECK_DTYPE_NOT_SUPPORT(bias, DTYPE_SUPPORT_LIST_BIAS, return false);
286	    }
287	    if (x3 != nullptr) {
288	        OP_CHECK_DTYPE_NOT_SUPPORT(x3, outDtypeSupport, return false);
289	        // 检查x3和output的数据类型是否相同
290	        OP_CHECK_DTYPE_NOT_SAME(x3, output, return false);
291	    }
292	    // 检查x1和x2的数据类型是否相同
293	    OP_CHECK_DTYPE_NOT_SAME(x1, x2, return false);
294	    // BF16场景，dequantScale的dtype与output一致，为BF16
295	    if (output->GetDataType() == op::DataType::DT_BF16 || dequantScale->GetDataType() == op::DataType::DT_BF16) {
296	        OP_CHECK_DTYPE_NOT_SAME(dequantScale, output, return false);
297	    }
298	    // pertokenScale必须为float32
299	    if (pertokenScale != nullptr) {
300	        OP_CHECK_DTYPE_NOT_SUPPORT(pertokenScale, DTYPE_SUPPORT_LIST_PERTOKEN, return false);
301	        // FP16场景，dequantScale的dtype与pertokenScale一致，为float32
302	        if (output->GetDataType() == op::DataType::DT_FLOAT16) {
303	            OP_CHECK_DTYPE_NOT_SAME(dequantScale, pertokenScale, return false);
304	        }
305	    }
306	    return true;
307	}
