309	bool MatmulAllReduceIsWeightNZFormat(const aclTensor *x2)
310	{
311	    aclFormat format = aclFormat::ACL_FORMAT_UNDEFINED;
312	    aclGetFormat(x2, &format);
313	    if (format == aclFormat::ACL_FORMAT_ND) {
314	        OP_LOGD("MatmulAllReduce, Recieved weight format is ACL_FORMAT_ND");
315	    }
316	    if (format == aclFormat::ACL_FORMAT_FRACTAL_NZ) {
317	        OP_LOGD("MatmulAllReduce, Recieved weight format is ACL_FORMAT_FRACTAL_NZ");
318	        uint64_t storageDimsNum = x2->GetStorageShape().GetDimNum();
319	        OP_LOGD("MatmulAllReduce, Shape is %lu", storageDimsNum);
320	        const uint64_t transdataNzDim = 4U;
321	        if (storageDimsNum == transdataNzDim) {
322	            return true;
323	        }
324	    }
325	    return false;
326	}
