334	        OP_LOGD("MatmulAllReduce, Shape is %lu", storageDimsNum);
335	        const uint64_t transdataNzDim = 4U;
336	        if (storageDimsNum == transdataNzDim) {
337	            return true;
338	        }
339	    }
