354	void QuantMatmulAllReduceProcessTransposedX2(const aclTensor *x2, uint64_t &x2Dim0, uint64_t &x2Dim1,
355	                                             ge::AscendString &x2ShapeStr)
356	{
357	    op::Shape x2ViewShape = x2->GetViewShape();
358	    x2ViewShape.SetDim(0, x2Dim0);
359	    x2ViewShape.SetDim(1, x2Dim1);
360	    if (QuantMatmulAllReduceIsAclnnPreTransposed(x2)) {
361	        x2ShapeStr = op::ToString(x2ViewShape);
362	    }
363	    OP_LOGD("MatmulAllReduce, x2 view shape is %s", x2ShapeStr.GetString());
