366	bool QuantMatmulAllReduceCheckPertokenScaleShape(const aclTensor *pertokenScale, const aclTensor *x1,
367	                                                 const size_t x1Len)
368	{
369	    // pertokenScale的shape为[m]
370	    if (pertokenScale != nullptr) {
371	        OP_CHECK_MIN_DIM(pertokenScale, ONE_DIM, return false);
372	        OP_CHECK_MAX_DIM(pertokenScale, ONE_DIM, return false);
373	        const size_t pertokenScaleLen = pertokenScale->GetViewShape().GetDimNum();
374	        size_t x1_m = 1;
375	        for (size_t dim = 0; dim < x1Len - 1; dim++) {
376	            x1_m *= x1->GetViewShape().GetDim(dim);
377	        }
378	        if (pertokenScaleLen != DIM_LEN_ONE || static_cast<size_t>(pertokenScale->GetViewShape().GetDim(0)) != x1_m) {
379	            OP_LOGE_FOR_INVALID_SHAPE("MatmulAllReduce", "pertokenScale",
380	                                      op::ToString(pertokenScale->GetViewShape()).GetString(),
381	                                      std::string("[" + std::to_string(x1_m) + "]").c_str());
382	            return false;
383	        }
384	    }
385	    return true;
386	}
387	
388	bool QuantMatmulAllReduceCheckDequantScale(const aclTensor *dequantScale, const op::Shape &outShape, size_t x1Len)
389	{
390	    OP_CHECK_MIN_DIM(dequantScale, ONE_DIM, return false);
391	    OP_CHECK_MAX_DIM(dequantScale, TWO_DIMS, return false);
392	    const size_t scaleLen = dequantScale->GetViewShape().GetDimNum();
393	    if (!(scaleLen == DIM_LEN_ONE && (dequantScale->GetViewShape().GetDim(0) == NUM_ONE ||
394	                                      dequantScale->GetViewShape().GetDim(0) == outShape.GetDim(x1Len - 1))) &&
395	        !(scaleLen == DIM_LEN_TWO && dequantScale->GetViewShape().GetDim(0) == NUM_ONE &&
396	          dequantScale->GetViewShape().GetDim(1) == outShape.GetDim(x1Len - 1))) {
397	        OP_LOGE_FOR_INVALID_SHAPE("MatmulAllReduce", "dequantScale",
398	                                  op::ToString(dequantScale->GetViewShape()).GetString(),
399	                                  std::string("[1] or [n] or [1,n], last dim should be " +
400	                                              std::to_string(outShape.GetDim(x1Len - 1)) + " or 1")
401	                                      .c_str());
402	        return false;
403	    }
404	    return true;
405	}
406	
407	bool QuantMatmulAllReduceCheckShape(const aclTensor *x1, const aclTensor *x2, const aclTensor *bias,
408	                                    const aclTensor *dequantScale, const aclTensor *pertokenScale, const aclTensor *x3,
409	                                    const aclTensor *output)
410	{
411	    OP_CHECK_MIN_DIM(x1, TWO_DIMS, return false);
412	    OP_CHECK_MAX_DIM(x1, THREE_DIMS, return false);
413	    if (QuantMatmulAllReduceIsWeightNZFormat(x2)) {
414	        return true;
415	    }
416	    // x2的维度为2维,x1的维度为2D或者3D，output的维数与x1一致,weightNZ场景下，x2可能为4维
417	    if (x2->GetViewShape().GetDimNum() != TWO_DIMS) {
418	        OP_LOGE_FOR_INVALID_SHAPEDIM_WITH_REASON("MatmulAllReduce", "x2",
419	                                                 (std::to_string(x2->GetViewShape().GetDimNum()) + "D").c_str(),
420	                                                 "The shape of x2 must be 2D.");
421	        return false;
422	    }
423	    uint64_t x2Dim0 =
424	        QuantMatmulAllReduceIsAclnnPreTransposed(x2) ? x2->GetViewShape().GetDim(1) : x2->GetViewShape().GetDim(0);
425	    uint64_t x2Dim1 =
426	        QuantMatmulAllReduceIsAclnnPreTransposed(x2) ? x2->GetViewShape().GetDim(0) : x2->GetViewShape().GetDim(1);
427	    auto x2ShapeStr = op::ToString(x2->GetViewShape());
428	    QuantMatmulAllReduceProcessTransposedX2(x2, x2Dim0, x2Dim1, x2ShapeStr);
429	    // 仅支持x2矩阵转置，x1不支持转置, x1.GetDimNum(1) == x2.GetDimNum(0)
430	    const size_t x1Len = x1->GetViewShape().GetDimNum();
431	    if (x1Len < 1 || x1Len > THREE_DIMS) {
432	        return false;
433	    }
434	    if (static_cast<uint64_t>(x1->GetViewShape().GetDim(x1Len - 1)) != x2Dim0) {
435	        OP_LOGE_FOR_INVALID_SHAPE_WITH_REASON(
436	            "MatmulAllReduce", "x1", op::ToString(x1->GetViewShape()).GetString(),
437	            std::string("The last dim of x1 must be equal to the first dim of x2, but x2 shape is " +
438	                        std::string(x2ShapeStr.GetString()))
439	                .c_str());
440	        return false;
441	    }
442	    // output的最后一维与x2的最后一维相同
443	    op::Shape outShape = x1->GetViewShape();
444	    outShape.SetDim(x1Len - 1, x2Dim1);
445	    OP_CHECK_SHAPE_NOT_EQUAL_WITH_EXPECTED_SIZE(output, outShape, return false);
446	
447	    // 判断output是否为空tensor
448	    if (output->IsEmpty()) {
449	        OP_LOGE_FOR_INVALID_SHAPE("MatmulAllReduce", "output", op::ToString(output->GetViewShape()).GetString(),
450	                                  "non-empty tensor");
451	        return false;
452	    }
453	
454	    // x1 shape [s,m,k], x2 shape [k,n], output shape [s,m,n], bias shape [n]
455	    if (bias != nullptr) {
456	        if (bias->GetViewShape().GetDimNum() != ONE_DIM) {
457	            OP_LOGE_FOR_INVALID_SHAPEDIM_WITH_REASON("MatmulAllReduce", "bias",
458	                                                     (std::to_string(bias->GetViewShape().GetDimNum()) + "D").c_str(),
459	                                                     "The shape of bias must be 1D.");
460	            return false;
461	        }
462	        op::Shape biasShape;
463	        biasShape.AppendDim(output->GetViewShape().GetDim(x1Len - 1));
464	        OP_CHECK_SHAPE_NOT_EQUAL_WITH_EXPECTED_SIZE(bias, biasShape, return false);
465	    }
466	    // x3 shape [s,m,n]
467	    if (x3 != nullptr) {
468	        OP_CHECK_SHAPE_NOT_EQUAL(x3, output, return false);
469	    }
470	    // scale和offset为per-tensor则shape为[1]，为per-channel则shape为[n]或者[1,n]
471	    if (!QuantMatmulAllReduceCheckDequantScale(dequantScale, outShape, x1Len)) {
472	        return false;
473	    }
474	    if (!QuantMatmulAllReduceCheckPertokenScaleShape(pertokenScale, x1, x1Len)) {
475	        return false;
476	    }
477	    return true;
478	}
