480	const aclTensor *QuantMatmulAllReduceTransTensor(const aclTensor *x2)
481	{
482	    uint64_t storageDimsNum = x2->GetStorageShape().GetDimNum();
483	    std::vector<int64_t> storageDims(storageDimsNum);
484	    for (uint64_t i = 0; i < storageDimsNum; i++) {
485	        storageDims[i] = x2->GetStorageShape().GetDim(i);
486	    }
487	
488	    uint64_t viewDimsNum = x2->GetViewShape().GetDimNum();
489	    std::vector<int64_t> viewDims;
490	    viewDims.resize(viewDimsNum);
491	    for (uint64_t i = 0; i < viewDimsNum; i++) {
492	        viewDims[i] = x2->GetViewShape().GetDim(i);
493	    }
494	
495	    viewDims[0] = x2->GetViewShape().GetDim(1);
496	    viewDims[1] = x2->GetViewShape().GetDim(0);
497	
498	    aclDataType dataType = aclDataType::ACL_DT_UNDEFINED;
499	    aclGetDataType(x2, &dataType);
500	    std::vector<int64_t> stride(viewDimsNum);
501	    auto transStride = x2->GetViewStrides();
502	    stride = std::vector<int64_t>(transStride.begin(), transStride.end());
503	    // transpose the two dimensions
504	    stride[0] = transStride[1];
505	    stride[1] = transStride[0];
506	
507	    auto offset = x2->GetViewOffset();
508	    aclFormat format = aclFormat::ACL_FORMAT_ND;
509	
510	    return aclCreateTensor(viewDims.data(), viewDimsNum, dataType, stride.data(), offset, format, storageDims.data(),
511	                           storageDimsNum, x2->GetTensor()->GetAddr());
512	}
513	
514	aclTensor *QuantMatmulAllReduceCopyTensor(const aclTensor *x2)
515	{
516	    uint64_t storageDimsNum = x2->GetStorageShape().GetDimNum();
517	    std::vector<int64_t> storageDims(storageDimsNum);
518	    for (size_t i = 0; i < storageDimsNum; i++) {
519	        storageDims[i] = x2->GetStorageShape().GetDim(i);
520	    }
521	    OP_LOGD("MatmulAllReduce, CopyTensor storageDimsNum is %lu.", storageDimsNum);
522	    aclDataType dataType = aclDataType::ACL_DT_UNDEFINED;
523	    aclGetDataType(x2, &dataType);
524	    std::vector<int64_t> stride(storageDimsNum, 1);
525	    for (int64_t i = static_cast<int64_t>(storageDimsNum - DIM_LEN_TWO); i >= 0; i--) {
526	        stride[i] = storageDims[i + 1] * stride[i + 1];
527	    }
528	    auto offset = x2->GetViewOffset();
529	    aclFormat format = aclFormat::ACL_FORMAT_UNDEFINED;
530	    auto stgFormat = ge::GetPrimaryFormat(x2->GetStorageFormat());
531	    if (stgFormat == Format::FORMAT_ND) {
532	        OP_LOGD("MatmulAllReduce, CopyTensor format is ACL_FORMAT_ND");
533	        format = aclFormat::ACL_FORMAT_ND;
534	    } else if (stgFormat == Format::FORMAT_FRACTAL_NZ) {
535	        format = aclFormat::ACL_FORMAT_FRACTAL_NZ;
536	    }
537	    return aclCreateTensor(storageDims.data(), storageDimsNum, dataType, stride.data(), offset, format,
538	                           storageDims.data(), storageDimsNum, x2->GetTensor()->GetAddr());
539	}
540	
541	// quant Inner
542	aclnnStatus InnerQuantMatmulAllReduceGetWorkspaceSize(const aclTensor *x1, const aclTensor *x2,
543	                                                      const aclTensor *biasOptional, const aclTensor *x3Optional,
544	                                                      const aclTensor *dequant, const aclTensor *pertokenScaleOptional,
545	                                                      const char *group, const char *reduceOp, int64_t commTurn,
546	                                                      const aclTensor *output, uint64_t *workspaceSize,
547	                                                      aclOpExecutor **executor)
548	{
549	    // 目前不支持x1进行transpose
550	    bool transposeX1 = false;
551	    bool transposeX2 = IsTransposeLastTwoDims(x2) || QuantMatmulAllReduceIsAclnnPreTransposed(x2);
552	    aclTensor *scale = nullptr;
553	    aclTensor *offset = nullptr;
554	    aclTensor *commQuantScale1Optional = nullptr;
555	    aclTensor *commQuantScale2Optional = nullptr;
556	    int64_t antiquantGroupSize = 0;
557	    auto tempX2 = x2;
558	    if (op::GetCurrentPlatformInfo().GetCurNpuArch() != NpuArch::DAV_2002 && QuantMatmulAllReduceIsWeightNZFormat(x2)) {
559	        if (x2->GetTensor() == nullptr) {
560	            OP_LOGE_WITH_INVALID_INPUT("MatmulAllReduce", "x2");
561	            return ACLNN_ERR_INNER_NULLPTR;
562	        }
563	        tempX2 = QuantMatmulAllReduceCopyTensor(x2);
564	    }
565	    if (NnopbaseSetHcclServerType) {
566	        if (op::GetCurrentPlatformInfo().GetCurNpuArch() == NpuArch::DAV_3510) {
567	            NnopbaseSetHcclServerType(executor, NnopbaseHcclServerType::NNOPBASE_HCCL_SERVER_TYPE_AICPU);
568	        }
569	    }
570	    uint64_t yDtype = static_cast<uint64_t>(output->GetDataType());
571	    const char *commModePtr = "ai_cpu";
572	    aclnnStatus ret = aclnnInnerMatmulAllReduceGetWorkspaceSize(
573	        x1, tempX2, biasOptional, x3Optional, scale, offset, dequant, pertokenScaleOptional, commQuantScale1Optional,
574	        commQuantScale2Optional, const_cast<char *>(group), const_cast<char *>(reduceOp), transposeX1, transposeX2,
575	        commTurn, antiquantGroupSize, 0, yDtype, 0, const_cast<char *>(commModePtr), output, workspaceSize, executor);
576	
577	    OP_LOGI("Group %s, reduce op %s, trans flag %u %u, ret %d.", group, reduceOp, transposeX1, transposeX2, ret);
578	#ifdef MC2_UT
579	    ret = 0;
580	#endif
581	    if (ret == 0) {
582	        if (NnopbaseDisableOptionalInput != nullptr && executor != nullptr && *executor != nullptr) {
583	            NnopbaseDisableOptionalInput(*executor, 4U); // 4 is input irIndex
584	            NnopbaseDisableOptionalInput(*executor, 5U); // 5 is input irIndex
585	            if (pertokenScaleOptional == nullptr) {
586	                NnopbaseDisableOptionalInput(*executor, 7U); // 7 is input irIndex
587	            }
588	            NnopbaseDisableOptionalInput(*executor, 8U); // 8 is input irIndex
589	            NnopbaseDisableOptionalInput(*executor, 9U); // 9 is input irIndex
590	        }
591	    }
592	    return ret;
593	}
