595	// 检查commMode入参是否合法
596	bool IsCommModeValid(const char *commModePtr)
597	{
598	    if (op::GetCurrentPlatformInfo().GetCurNpuArch() == NpuArch::DAV_3510) {
599	        if (commModePtr == nullptr) {
600	            OP_LOGE(ACLNN_ERR_PARAM_INVALID, "Its new Aclnn interface for A5, commModePtr should not be nullptr!");
601	            return false;
602	        }
603	        if (strcmp(commModePtr, COMM_MODE_AICPU) == 0)
604	            return true;
605	        if (strcmp(commModePtr, COMM_MODE_CCU) == 0)
606	            return true;
607	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "For A5, commMode only support 'ccu' or 'ai_cpu', but it is '%s'.",
608	                commModePtr);
609	    } else {
610	        if (commModePtr == nullptr)
611	            return true;
612	        if (strcmp(commModePtr, COMM_MODE_AICPU) == 0)
613	            return true;
614	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "For A2, commMode only support nullptr or 'ai_cpu', but it is '%s'.",
615	                commModePtr);
616	    }
617	    return false;
618	}
